    "--summary": "summary",
    "--until-changes": "until_changes",
    "--until-fail": "until_fail",
    "--until-same": "until_same",
    "--until-success": "until_success",
    "--version": "version",
}

SHORT_FLAGS = {
    "D": "error_duration",
    "h": "help",
    "l": "only_last",
    "i": "stdin",
    "C": "until_changes",
    "f": "until_fail",
    "S": "until_same",
