SHORT_OPTIONS = {
    "b": ("count_by_s", "--count-by <count_by>"),
    "e": ("every_s", "--every <every>"),
    "d": ("for_duration_s", "--for-duration <for_duration>"),
    "n": ("num_s", "--num <num>"),
    "o": ("offset_s", "--offset <offset>"),
    "c": ("until_contains", "--until-contains <until_contains>"),
    "r": ("until_error", "--until-error <until_error>"),
    "m": ("until_match", "--until-match <until_match>"),
    "t": ("until_time_s", "--until-time <until_time>"),
}

# Human-readable names for validation errors.
DISPLAY_OPT = {
    "num_s": "--num <num>",
    "count_by_s": "--count-by <count_by>",
    "offset_s": "--offset <offset>",
    "every_s": "--every <every>",
    "for_duration_s": "--for-duration <for_duration>",
    "until_time_s": "--until-time <until_time>",
    "until_match": "--until-match <until_match>",
}


@dataclass
class Options:
    error_duration: bool = False
    only_last: bool = False
    stdin: bool = False
    summary: bool = False
    until_changes: bool = False
    until_fail: bool = False
    until_same: bool = False
    until_success: bool = False

    count_by_s: str = "1"
    every_s: str = "1us"
    for_s: Optional[str] = None
    for_duration_s: Optional[str] = None
    num_s: Optional[str] = None
    offset_s: str = "0"
    until_contains: Optional[str] = None
    until_error: Optional[str] = None
    until_match: Optional[str] = None
    until_time_s: Optional[str] = None

    input: List[str] = field(default_factory=list)


def _print_stdout(s: str) -> None:
    sys.stdout.write(s)
    sys.stdout.flush()


def _print_stderr(s: str) -> None:
    sys.stderr.write(s)
    sys.stderr.flush()


def _usage_for(option_usage: Optional[str] = None) -> str:
    if option_usage:
        return f"USAGE:\n    executable {option_usage}\n"
    return "USAGE:\n    executable [FLAGS] [OPTIONS] [input]...\n"


def error_unexpected(arg: str, option_usage: Optional[str] = None) -> int:
    _print_stderr(
        f"error: Found argument '{arg}' which wasn't expected, or isn't valid in this context\n\n"
        + _usage_for(option_usage)
        + "\nFor more information try --help\n"
    )
    return 1


def error_requires(option_usage: str) -> int:
    # The observed binary uses Clap's canonical long option in this diagnostic.
    _print_stderr(
        f"error: The argument '{option_usage}' requires a value but none was supplied\n\n"
        + _usage_for("--count-by <count_by> --every <every> --num <num> --offset <offset>" if option_usage == "--num <num>" else option_usage)
        + "\nFor more information try --help\n"
    )
    return 1


def error_invalid(field_name: str, message: str) -> int:
    opt = DISPLAY_OPT.get(field_name, field_name)
    _print_stderr(f"error: Invalid value for '{opt}': {message}\n")
    return 1


def is_help_or_version_token(tok: str) -> Optional[str]:
    if tok in ("--help", "-h"):
        return "help"
    if tok in ("--version", "-V"):
        return "version"
    # Short clusters: Clap stops immediately if h/V occurs in a cluster.
    if tok.startswith("-") and not tok.startswith("--") and len(tok) > 2:
        body = tok[1:]
        if "h" in body:
            return "help"
        if "V" in body:
            return "version"
    return None


def parse_args(argv: List[str]) -> Tuple[Optional[Options], int]:
    opts = Options()
    i = 0
    after_double_dash = False
    while i < len(argv):
        arg = argv[i]
        if after_double_dash:
            opts.input.append(arg)
            i += 1
            continue

        hv = is_help_or_version_token(arg)
        if hv == "help":
            _print_stdout(HELP_TEXT)
            return None, 0
        if hv == "version":
            _print_stdout(VERSION_TEXT)
            return None, 0

        if arg == "--":
            after_double_dash = True
            i += 1
            continue

        if arg.startswith("--") and len(arg) > 2:
            if "=" in arg:
                name, val = arg.split("=", 1)
                has_inline = True
            else:
                name, val = arg, None
                has_inline = False
            if name in LONG_FLAGS:
                if has_inline:
                    return None, error_unexpected(arg)
                setattr(opts, LONG_FLAGS[name], True)
                i += 1
                continue
            if name in LONG_OPTIONS:
                field_name, usage = LONG_OPTIONS[name]
                if not has_inline:
                    if i + 1 >= len(argv):
                        return None, error_requires(usage)
                    nxt = argv[i + 1]
                    hv_next = is_help_or_version_token(nxt)
                    if hv_next == "help":
                        _print_stdout(HELP_TEXT)
                        return None, 0
                    if hv_next == "version":
                        _print_stdout(VERSION_TEXT)
                        return None, 0
                    if nxt.startswith("-"):
                        return None, error_unexpected(nxt, usage)
                    val = nxt
                    i += 1
                setattr(opts, field_name, val)
                i += 1
                continue
            return None, error_unexpected(arg)

        if arg.startswith("-") and len(arg) > 1:
            # Parse clusters such as -ln2, -sl, and attached values like -e1ms.
            j = 1
            consumed_option_value = False
            while j < len(arg):
                ch = arg[j]
                if ch in ("h", "V"):
                    if ch == "h":
                        _print_stdout(HELP_TEXT)
                    else:
                        _print_stdout(VERSION_TEXT)
                    return None, 0
                if ch in SHORT_FLAGS:
                    setattr(opts, SHORT_FLAGS[ch], True)
                    j += 1
                    continue
                if ch in SHORT_OPTIONS:
                    field_name, usage = SHORT_OPTIONS[ch]
                    if j + 1 < len(arg):
                        val = arg[j + 1 :]
                        if val.startswith("="):
                            val = val[1:]
                        setattr(opts, field_name, val)
                        consumed_option_value = True
                        j = len(arg)
                        break
                    else:
                        if i + 1 >= len(argv):
                            return None, error_requires(usage)
                        nxt = argv[i + 1]
                        hv_next = is_help_or_version_token(nxt)
                        if hv_next == "help":
                            _print_stdout(HELP_TEXT)
                            return None, 0
                        if hv_next == "version":
                            _print_stdout(VERSION_TEXT)
                            return None, 0
                        if nxt.startswith("-"):
                            return None, error_unexpected(nxt, usage)
                        setattr(opts, field_name, nxt)
                        i += 1
                        consumed_option_value = True
                        j = len(arg)
                        break
                return None, error_unexpected(arg)
            i += 1
            continue

        opts.input.append(arg)
        i += 1

    return opts, 0


def parse_float_for(field_name: str, value: str) -> Tuple[Optional[float], Optional[int]]:
    try:
        # Rust's f64 parser accepts NaN/inf; Python accepts these too (case-insensitive).
        return float(value), None
    except Exception:
        return None, error_invalid(field_name, "invalid float literal")


def precision_from_count_by(s: str) -> int:
    # Observed COUNT is formatted with fixed precision equal to the number of
    # digits after the decimal point in count-by's textual value (before exponent).
    mantissa = s
    for sep in ("e", "E"):
        if sep in mantissa:
            mantissa = mantissa.split(sep, 1)[0]
            break
    if "." in mantissa:
        return len(mantissa.split(".", 1)[1])
    return 0


