    "d": 86400.0,
    "day": 86400.0,
    "days": 86400.0,
    "w": 604800.0,
    "week": 604800.0,
    "weeks": 604800.0,
}


def parse_duration_text(text: str, field_name: str) -> Tuple[Optional[float], Optional[int]]:
    i = 0
    total = 0.0
    n = len(text)
    while i < n:
        if not text[i].isdigit():
            return None, error_invalid(field_name, f"expected number at {i}")
        start_num = i
        while i < n and text[i].isdigit():
            i += 1
        # Unit must start immediately after the number. A non-ascii-alpha (such
        # as '.' or a space) is reported as an invalid character at its position.
        unit_start = i
        if i >= n:
            return None, error_invalid(field_name, f"unknown unit at {unit_start}-{unit_start}")
        if not ("a" <= text[i].lower() <= "z"):
            return None, error_invalid(field_name, f"invalid character at {i}")
        while i < n and ("a" <= text[i].lower() <= "z"):
            i += 1
        unit = text[unit_start:i]
        factor = _DURATION_UNITS.get(unit)
        if factor is None:
            return None, error_invalid(field_name, f"unknown unit at {unit_start}-{i}")
        try:
            amount = int(text[start_num:unit_start])
        except Exception:
            return None, error_invalid(field_name, f"expected number at {start_num}")
        total += amount * factor
    if n == 0:
        return None, error_invalid(field_name, "expected number at 0")
    return total, None


def parse_until_time(text: str) -> Tuple[Optional[float], Optional[int]]:
    try:
        dt = _dt.datetime.strptime(text, "%Y-%m-%d %H:%M:%S")
        dt = dt.replace(tzinfo=_dt.timezone.utc)
        return dt.timestamp(), None
    except Exception:
        return None, error_invalid("until_time_s", "timestamp format is invalid")


def compile_regex(pattern: str) -> Tuple[Optional[re.Pattern], Optional[int]]:
    try:
        return re.compile(pattern), None
    except re.error as e:
        # Match the common Rust-regex diagnostic for an unclosed character class;
        # otherwise provide a compact invalid-value message.
        if pattern == "[":
            _print_stderr(
                "error: Invalid value for '--until-match <until_match>': regex parse error:\n"
                "    [\n"
                "    ^\n"
                "error: unclosed character class\n"
            )
        else:
            _print_stderr(f"error: Invalid value for '--until-match <until_match>': {e}\n")
        return None, 1


def count_limit_from_num(num: Optional[float]) -> Optional[int]:
    if num is None:
        return None
    if math.isnan(num):
        return 0
    if math.isinf(num):
        return None if num > 0 else 0
    if num <= 0:
        return 0
    return int(num)


def format_count(offset: float, count_by: float, actual: int, precision: int) -> str:
    try:
        val = offset + count_by * float(actual)
        return format(val, f".{precision}f")
    except Exception:
        # Python's formatting handles NaN/inf; this is just a fallback.
        return str(offset + count_by * float(actual))


def read_stdin_items(force: bool) -> List[str]:
    if not force and sys.stdin.isatty():
        return []
    try:
        data = sys.stdin.buffer.read()
    except Exception:
        return []
    if data == b"":
        return []
    # Rust BufRead::lines-style behavior: split on line endings, no trailing
    # empty line for a final newline, but preserve intentional blank lines.
    text = data.decode(errors="replace")
    return text.splitlines()


def print_command_output(data: bytes) -> None:
    if not data:
        return
    try:
        sys.stdout.buffer.write(data)
        if not data.endswith(b"\n"):
            sys.stdout.buffer.write(b"\n")
        sys.stdout.buffer.flush()
    except BrokenPipeError:
        raise


def run_command(command: str, env: dict) -> Tuple[bytes, int]:
    try:
        cp = subprocess.run(
            command,
            shell=True,
            stdin=subprocess.DEVNULL,
            stdout=subprocess.PIPE,
            stderr=subprocess.STDOUT,
            env=env,
        )
        code = cp.returncode
        # Shell return codes are non-negative in normal cases; keep signal
        # encodings close to common shell convention if ever needed.
        if code < 0:
            code = 128 + (-code)
        return cp.stdout, code
    except FileNotFoundError as e:
        msg = (str(e) + "\n").encode()
        return msg, 127


def decoded_output(data: bytes) -> str:
    return data.decode(errors="replace")


def main(argv: List[str]) -> int:
    parsed, code = parse_args(argv)
    if parsed is None:
        return code
    opts = parsed

    if not opts.input:
        _print_stdout("No command supplied, exiting.\n")
        return 0

    num_val = None
    if opts.num_s is not None:
        num_val, err = parse_float_for("num_s", opts.num_s)
        if err is not None:
            return err
    count_by, err = parse_float_for("count_by_s", opts.count_by_s)
    if err is not None:
        return err
    offset, err = parse_float_for("offset_s", opts.offset_s)
    if err is not None:
        return err

    every, err = parse_duration_text(opts.every_s, "every_s")
    if err is not None:
        return err
    for_duration = None
    if opts.for_duration_s is not None:
        for_duration, err = parse_duration_text(opts.for_duration_s, "for_duration_s")
        if err is not None:
            return err

    until_time_ts = None
    if opts.until_time_s is not None:
        until_time_ts, err = parse_until_time(opts.until_time_s)
        if err is not None:
            return err

    regex_obj = None
    if opts.until_match is not None:
        regex_obj, err = compile_regex(opts.until_match)
        if err is not None:
            return err

    precision = precision_from_count_by(opts.count_by_s)
    command = " ".join(opts.input)

    items: List[str] = []
    if opts.for_s is not None:
        items.extend(opts.for_s.split(","))
    items.extend(read_stdin_items(opts.stdin))
    have_item_source = len(items) > 0

    max_iterations = count_limit_from_num(num_val)
    finite_items_limit: Optional[int] = None
    if max_iterations is None and have_item_source:
        finite_items_limit = len(items)

    start_time = time.time()
    total_runs = 0
    successes = 0
    failures: List[int] = []
    last_output = b""
    first_output: Optional[bytes] = None
    actual = 0
    ended_by_duration = False

    try:
        while True:
            # Finite limits are checked before elapsed-time limits; this matches
            # -D with --num 0 / final sleep precedence.
            if max_iterations is not None and actual >= max_iterations:
                break
            if finite_items_limit is not None and actual >= finite_items_limit:
                break
            if for_duration is not None and (time.time() - start_time) >= for_duration:
                ended_by_duration = True
                break
            if until_time_ts is not None and time.time() >= until_time_ts:
                break

            env = os.environ.copy()
            env["COUNT"] = format_count(offset, count_by, actual, precision)
            env["ACTUALCOUNT"] = str(actual)
            if have_item_source:
                if actual < len(items):
                    env["ITEM"] = items[actual]
                else:
                    env["ITEM"] = items[-1]

            out, status = run_command(command, env)
            total_runs += 1
            if status == 0:
                successes += 1
            else:
                failures.append(status)
            last_output = out

            if not opts.only_last:
                print_command_output(out)

            text_out = decoded_output(out)
            should_stop = False
            if opts.until_success and status == 0:
                should_stop = True
            if opts.until_fail and status != 0:
                should_stop = True
            if opts.until_error is not None and str(status) == opts.until_error:
                should_stop = True
            if opts.until_contains is not None and opts.until_contains in text_out:
                should_stop = True
            if regex_obj is not None and regex_obj.search(text_out) is not None:
                should_stop = True

            if opts.until_changes or opts.until_same:
                if first_output is None:
                    first_output = out
                else:
                    if opts.until_changes and out != first_output:
                        should_stop = True
                    if opts.until_same and out == first_output:
                        should_stop = True

            if should_stop:
                break

            actual += 1
            # The original sleeps after ordinary finite iterations too; stop
            # conditions are the notable case that avoids the final sleep.
            if every > 0:
                time.sleep(every)
            elif every == 0:
                # Yield very briefly without imposing a real delay.
                pass

    except BrokenPipeError:
        return 0
    except KeyboardInterrupt:
        # The observed behavior is mostly intended for Ctrl-C; exiting quietly is
        # the least surprising approximation.
        return 0

    if opts.only_last:
        print_command_output(last_output)

    if opts.summary:
        _print_stdout(f"Total runs:\t{total_runs}\n")
        _print_stdout(f"Successes:\t{successes}\n")
        if failures:
            joined = ", ".join(str(x) for x in failures)
            _print_stdout(f"Failures:\t{len(failures)} ({joined})\n")
        else:
            _print_stdout("Failures:\t0\n")

    if opts.error_duration and opts.for_duration_s is not None and ended_by_duration:
        return 124
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
